logging.basicConfig()
from app.network import configure_hub_http, current_revision
from huggingface_hub import HfApi
seen = []
def handler(req):
    seen.append(req)
    if "missing" in str(req.url): return httpx2.Response(404, headers={"X-Error-Code": "RepoNotFound"}, json={"error": "nope"})
    if "down" in str(req.url): raise httpx2.ConnectError("boom", request=req)
    if "slow" in str(req.url): raise httpx2.ReadTimeout("slow", request=req)
    return httpx2.Response(200, json={"id": "a/b", "sha": "deadbeef", "siblings": []})
configure_hub_http(httpx2.MockTransport(handler))
print(current_revision("a/b"))
r = seen[-1]; print(r.url, r.headers["X-Acme-Job"], r.headers["user-agent"][:40], r.extensions["timeout"])
print(current_revision("a/down"), current_revision("a/slow"))
try: current_revision("a/missing")
except Exception as e: print("raised", type(e).__name__)
HfApi().list_repo_files("a/b"); print(seen[-1].headers["X-Acme-Job"])
EOF
pytest -q 2>&1 | tail -3

